import {TOOLS,CATEGORY_NAMES,THEMES,ext,base,bytes,validateFile,localOutline,validateOutline,buildPresentation} from './core.mjs';
import {loadScript,readText,convertFile,imagesToPdf,zipOutputs,stopVideoEngine} from './engine.mjs';
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}"${cls?` class="${cls}"`:''}></i>`;
const safeGet=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
const state={route:'home',filter:'all',search:'',favorites:safeGet('forma-favorites',[]),tasks:safeGet('forma-tasks',[]).map(t=>({...t,url:null})),ppt:{mode:'prompt',text:'',source:'',fileName:'',pages:8,theme:'green',outline:[],useAI:false,generating:false},api:{endpoint:'https://api.openai.com/v1',model:'gpt-4.1-mini',key:''}};
let modal=null,toastTimer;const runtimeURLs=new Set();
function icons(){window.lucide?.createIcons();}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),5000);}
function newURL(blob){const url=URL.createObjectURL(blob);runtimeURLs.add(url);return url;}
function download(url,name){const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();}
function trackTask(name,tool,status='success',result=null,error=''){
  const task={id:crypto.randomUUID(),name,tool,status,createdAt:Date.now(),output:result?.name||'',size:result?.blob?.size||0,url:result?newURL(result.blob):null,error};state.tasks.unshift(task);state.tasks=state.tasks.slice(0,30);save('forma-tasks',state.tasks.map(({url,...t})=>t));$('#taskCount').textContent=state.tasks.length;return task;
}
function dateString(){return new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'short'}).format(new Date());}
function formatIcons(tool){return `<div class="format-icons"><span class="format-icon ${tool.color}">${icon(tool.icon)}${tool.from}</span>${icon('arrow-right')}<span class="format-icon ${tool.targetColor}">${icon(tool.to==='PPTX'?'presentation':tool.to==='PNG'?'image':'file-text')}${tool.to}</span></div>`;}
function toolCard(tool){const saved=state.favorites.includes(tool.id);return `<article class="tool-card" role="button" tabindex="0" data-tool="${tool.id}" aria-label="打开${tool.name}"><div class="tool-card-top">${formatIcons(tool)}<button class="favorite-btn${saved?' saved':''}" data-favorite="${tool.id}" aria-label="${saved?'取消收藏':'收藏'}${tool.name}" aria-pressed="${saved}">${icon('star')}</button></div><h3>${tool.name}${tool.badge?`<span class="pill ${tool.badge==='热门'?'hot':'new'}">${tool.badge}</span>`:''}</h3><p>${tool.desc}</p><div class="card-footer"><span class="tool-label">${icon(tool.category==='ppt'?'sparkles':'shield-check')}${tool.category==='ppt'?'支持编辑 · .PPTX':'浏览器本地处理'}</span>${icon('arrow-up-right')}</div></article>`;}
function taskRows(tasks){return tasks.map(t=>`<div class="task-row"><div class="task-name">${icon(t.status==='success'?'file-check-2':'file-warning')}<span title="${esc(t.name)}">${esc(t.name)}</span></div><span class="status-badge${t.status==='error'?' error':''}">${icon(t.status==='success'?'circle-check':'circle-alert')}${t.status==='success'?'已完成':'转换失败'}</span><span class="task-meta">${esc(t.tool)} · ${new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(t.createdAt)}</span><button class="download-btn" data-task="${t.id}" title="${t.url?'下载文件':t.status==='error'?esc(t.error):'刷新后文件已释放，点击了解'}">${icon(t.url?'download':t.status==='error'?'circle-help':'info')}${t.url?'下载':t.status==='error'?'详情':'说明'}</button></div>`).join('');}
function historyHTML(full=false){const tasks=full?state.tasks:state.tasks.slice(0,3);return `<section class="history-section"><div class="section-title"><h2>最近任务${full?'':`<small>把每一次处理，都变得井井有条</small>`}</h2>${full?`<button class="clear-button" id="clearHistory">清空记录</button>`:`<a href="#history">查看全部 ${icon('arrow-right')}</a>`}</div><div class="history-box"><div class="table-head"><span>文件名称</span><span>状态</span><span>处理类型与时间</span><span>操作</span></div>${tasks.length?taskRows(tasks):`<div class="empty-history">${icon('folder-open')}<div><strong>你的下一次高效，从这里开始</strong><p>完成的转换和 PPT 生成任务会显示在这里</p></div></div>`}</div></section>`;}
function heroHTML(){return `<div class="hero-grid"><section class="upload-card"><div class="card-topline">${icon('arrow-left-right')}快速转换<span class="quiet">无需安装 · 即选即用</span></div><div class="dropzone" id="homeDrop" tabindex="0" role="button" aria-label="上传文件进行转换"><div class="upload-illustration"><span class="file-back"></span><span class="file-front"></span><span class="file-circle">${icon('arrow-up')}</span></div><div class="dropzone-title"><strong>拖入文件</strong>，剩下的交给我们</div><button class="primary-btn" id="uploadButton">${icon('plus')}选择文件</button><div class="dropzone-foot">PDF、Word、图片、视频及音频 · 支持批量处理</div></div></section><section class="ppt-hero"><span class="new-tag">${icon('sparkles')}让表达更进一步</span><h2>从一个想法，<br>到一份<span>好演示。</span></h2><p>上传文档或输入主题<br>一键生成可编辑的 PPT，让灵感更快成形。</p><button class="lime-btn" data-route="ppt">开始创作 ${icon('arrow-up-right')}</button><div class="slide-illustration" aria-hidden="true"><div class="mini-slide-back"></div><div class="mini-slide-front"><span class="slide-number">IDEAS IN MOTION</span><b>让想法，发生。</b><div class="slide-lines"></div><div class="slide-chart"><i></i><i></i><i></i></div></div><span class="sparkle">✧</span></div></section></div>`;}
function toolSectionHTML(){const category=state.route==='home'?'all':state.route;return `<section class="tools-section"><div class="section-title"><h2>${category==='all'?'常用工具':CATEGORY_NAMES[category]} <small id="toolCountLabel"></small></h2><button class="text-button" id="showAllTools">${state.showAll?'收起工具':'探索全部工具'} ${icon('arrow-right')}</button></div><div class="tools-toolbar"><div class="tabs" role="group" aria-label="工具分类">${[['all','全部工具'],['document','文档'],['image','图片'],['video','视频与音频']].map(([id,label])=>`<button data-filter="${id}" class="${(state.route==='home'?state.filter:state.route)===id?'active':''}" aria-pressed="${(state.route==='home'?state.filter:state.route)===id}">${label}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="searchInput" aria-label="搜索转换工具" placeholder="搜索工具，例如 PDF 转 Word" value="${esc(state.search)}"><kbd>/</kbd></label></div><div class="tool-grid" id="toolGrid"></div></section>`;}
function renderTools(){let tools=TOOLS.filter(t=>state.route!=='favorites'||state.favorites.includes(t.id));const category=state.route==='home'?state.filter:state.route==='favorites'?'all':state.route;if(category!=='all')tools=tools.filter(t=>t.category===category||(category==='image'&&t.id==='image-pdf'));if(state.search.trim()){const q=state.search.toLowerCase().replace(/\s/g,'');tools=tools.filter(t=>(t.name+t.from+t.to+t.desc+t.ext.join('')).toLowerCase().replace(/\s/g,'').includes(q));}if(state.route==='home'&&state.filter==='all'&&!state.search&&!state.showAll)tools=tools.slice(0,6);
  $('#toolGrid').innerHTML=tools.length?tools.map(toolCard).join(''):`<div class="empty-state">${icon(state.route==='favorites'?'star':'search')}<p>${state.route==='favorites'?'还没有收藏工具，点击工具卡片右上角的星标即可收藏。':'没有找到匹配的工具，试试 PDF、图片或视频。'}</p></div>`;
  $('#toolCountLabel').textContent=state.route==='favorites'?`${tools.length} 个工具`:'为日常工作，省下更多时间';icons();
}
function render(){const route=state.route;$('#breadcrumb').textContent=CATEGORY_NAMES[route]||CATEGORY_NAMES.home;$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===route));$('#taskCount').textContent=state.tasks.length;
  if(route==='ppt'){renderPpt();icons();return;}
  if(route==='history'){$('#main').innerHTML=`<div class="fade-in history-page"><div class="page-intro"><div><div class="eyebrow">YOUR WORK, IN ONE PLACE</div><h1>每一份文件，都有迹可循。</h1><p>记录保存在此浏览器。下载文件仅在本次会话保留，请及时保存。</p></div><button class="ghost-btn" data-route="home">${icon('plus')}新建转换</button></div>${historyHTML(true)}</div>`;icons();return;}
  const intros={document:['文档格式，轻松搞定。','从 PDF 到 Word，从图片到文档，让内容继续流动。'],image:['每一张图，都恰到好处。','转换图片格式、调整质量，为下一次使用做好准备。'],video:['换一种格式，继续精彩。','视频格式互转、音轨提取，全部在你的浏览器里完成。'],favorites:['常用的，放在手边。','把喜欢的工具收集起来，让下一次工作更顺手。']};const intro=intros[route];
  $('#main').innerHTML=`<div class="fade-in"><div class="page-intro"><div><div class="eyebrow">A LITTLE LESS BUSY. A LOT MORE DONE.</div><h1>${intro?intro[0]:'文件格式，<em>自由转换。</em>'}</h1><p>${intro?intro[1]:'转换文件，整理灵感。把繁琐留给工具，把时间留给创造。'}</p></div><span class="date-label">${icon('sun')} ${dateString()}</span></div>${route==='home'?heroHTML():route==='favorites'?'':`<div class="category-banner">${icon(route==='document'?'files':route==='image'?'image':'clapperboard')}<div><strong>文件留在设备上，效率就在指尖</strong>${route==='video'?'单个文件最高 80 MB，建议使用最新版桌面浏览器。':'选择下方工具开始转换，支持拖入文件与批量下载。'}</div></div>`}${toolSectionHTML()}${route==='home'?historyHTML():''}</div>`;
  renderTools();const drop=$('#homeDrop');if(drop){wireDrop(drop,files=>quickFiles(files));drop.addEventListener('click',()=>$('#quickUpload').click());drop.addEventListener('keydown',e=>{if(e.target===drop&&['Enter',' '].includes(e.key)){e.preventDefault();$('#quickUpload').click();}});}icons();
}
function routeTo(route){if(!CATEGORY_NAMES[route])route='home';if(state.ppt.generating&&route!=='ppt'){toast('正在生成内容，请稍候完成');return;}state.route=route;state.filter=route==='home'?'all':route;state.search='';$('.sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>routeTo(location.hash.slice(1)||'home'));
function navigate(route){if(location.hash==='#'+route)routeTo(route);else location.hash=route;}
function wireDrop(element,callback){for(const type of ['dragover','dragenter'])element.addEventListener(type,e=>{e.preventDefault();element.classList.add('dragging');});for(const type of ['dragleave','drop'])element.addEventListener(type,e=>{e.preventDefault();element.classList.remove('dragging');});element.addEventListener('drop',e=>callback([...e.dataTransfer.files]));}
function quickFiles(files){if(!files.length)return;const e=ext(files[0].name);let tool=TOOLS.find(t=>t.id===(e==='pdf'?'pdf-word':['docx','txt','md'].includes(e)?'word-pdf':['jpg','jpeg','png','webp','gif','bmp','avif'].includes(e)?'image-convert':['mp3','wav','aac','m4a','flac','ogg','opus'].includes(e)?'audio-convert':'video-convert'));openConversion(tool.id,files);}
$('#quickUpload').addEventListener('change',e=>{quickFiles([...e.target.files]);e.target.value='';});
document.addEventListener('click',e=>{
  const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}
  const route=e.target.closest('[data-route]');if(route){navigate(route.dataset.route);return;}
  const favorite=e.target.closest('[data-favorite]');if(favorite){e.stopPropagation();const id=favorite.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save('forma-favorites',state.favorites);renderTools();return;}
  const card=e.target.closest('[data-tool]');if(card){card.dataset.tool==='ppt-create'?navigate('ppt'):openConversion(card.dataset.tool);return;}
  const filter=e.target.closest('[data-filter]');if(filter){const value=filter.dataset.filter;if(state.route!=='home'&&state.route!=='favorites'){state.route='home';state.filter=value;history.replaceState(null,'','#home');render();}else{state.filter=value;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===value);b.setAttribute('aria-pressed',String(b.dataset.filter===value));});renderTools();}return;}
  const taskBtn=e.target.closest('[data-task]');if(taskBtn){const t=state.tasks.find(t=>t.id===taskBtn.dataset.task);if(t?.url)download(t.url,t.output);else if(t?.status==='error')showInfo('任务详情',`<p>${esc(t.error)}</p><p>请检查源文件和工具支持范围后重新转换。</p>`);else showInfo('文件已从内存释放','<p>为保护隐私，转换文件只保存在本次页面会话的内存中。刷新或关闭页面后需要重新转换。</p><p>任务记录只保留文件名、处理类型和时间。请在完成后及时下载结果。</p>');return;}
  if(e.target.closest('#showAllTools')){state.showAll=!state.showAll;$('#showAllTools').innerHTML=(state.showAll?'收起工具':'探索全部工具')+' '+icon('arrow-right');renderTools();}
  if(e.target.closest('#clearHistory')){for(const t of state.tasks)if(t.url){URL.revokeObjectURL(t.url);runtimeURLs.delete(t.url);}state.tasks=[];save('forma-tasks',[]);render();toast('任务记录已清空');}
});
document.addEventListener('keydown',e=>{const card=e.target.closest('[data-tool]');if(card&&e.target===card&&['Enter',' '].includes(e.key)){e.preventDefault();card.click();}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){const input=$('#searchInput');if(input){e.preventDefault();input.focus();}}});
document.addEventListener('input',e=>{if(e.target.id==='searchInput'){state.search=e.target.value;renderTools();}});
$('.mobile-menu').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
$('.sidebar').addEventListener('click',e=>{if(e.offsetX>230&&e.target===$('.sidebar'))$('.sidebar').classList.remove('open');});
function showInfo(title,body){$('#infoContent').innerHTML=`<div class="dialog-head"><div><h2>${title}</h2></div><button class="close-btn" data-close-info aria-label="关闭">${icon('x')}</button></div><div class="info-body">${body}</div><div class="dialog-actions"><button class="primary-btn" data-close-info>知道了</button></div>`;icons();if(!$('#infoDialog').open)$('#infoDialog').showModal();$$('[data-close-info]').forEach(b=>b.onclick=()=>$('#infoDialog').close());}
function showPrivacy(){showInfo('你的文件，只属于你','<p>图片、文档与视频转换在浏览器中运行。原始文件和转换结果不会上传至我们的网站服务器。视频首次使用时会下载本地 FFmpeg 引擎。</p><h3>PPT 创作与 AI</h3><p>本地模板排版无需联网发送内容。如果你主动启用 AI，输入的主题或提取的文档文字会发送到你配置的模型接口，请确认该服务的数据政策。网站不会保存你的 API 密钥，刷新即清除。</p><h3>记录与下载</h3><p>工具收藏和任务元数据（文件名、类型、时间）保存在此浏览器的本地存储中。文件结果仅在内存中保留，刷新后释放。可在「最近任务」清除记录。</p><p>网页字体可能由 Google Fonts 提供，转换引擎与文件处理库来自本站。</p>');}
$('#privacyInfo').onclick=showPrivacy;$('#footerPrivacy').onclick=showPrivacy;
$('#helpBtn').onclick=()=>showInfo('让文件转换更顺手','<p>1. 选择工具，或将文件拖入首页上传区。</p><p>2. 选择输出格式与质量，点击「开始转换」。</p><p>3. 下载单个结果，或把批量结果打包下载。</p><h3>功能与边界</h3><p>PDF 转 Word 适用于可提取文字的 PDF，以内容编辑为目标，复杂版式不会复原；扫描件暂不支持 OCR。Word 转 PDF 会把文字重新排版为图片型 PDF。</p><p>视频/音频转换首次加载引擎约 31 MB，建议使用桌面 Chrome / Edge，单个文件最高 80 MB。受损文件、部分编码或设备内存不足可能导致转换失败。</p><p>PPT 支持 TXT、Markdown、DOCX、PDF 导入。本地模式根据内容生成排版与大纲；启用 AI 后可根据主题扩写。导出文本与图形均可在 PowerPoint 中编辑。</p>');
function openSettings(){const a=state.api;$('#infoContent').innerHTML=`<div class="dialog-head"><div><h2>AI 创作设置</h2><p>可选配置 · 兼容 Chat Completions 的模型接口</p></div><button class="close-btn" data-close-settings aria-label="关闭">${icon('x')}</button></div><form id="apiForm"><div class="info-body"><div class="note">默认使用本地模板，无需密钥。启用 AI 后，提示词或文档文字会发送到下方接口；密钥仅保存在本页内存，刷新即清除。</div><label class="field"><span>接口基础地址</span><input id="apiEndpoint" type="url" value="${esc(a.endpoint)}" required placeholder="https://your-provider.com/v1"><small>服务需允许浏览器跨域调用，路径会自动补充 /chat/completions。</small></label><label class="field"><span>模型名称</span><input id="apiModel" value="${esc(a.model)}" required autocomplete="off" placeholder="填写服务商提供的模型 ID"></label><label class="field"><span>API 密钥</span><input id="apiKey" type="password" value="${esc(a.key)}" autocomplete="off" placeholder="填写后可启用 AI 创作"><small>请使用限额密钥；仅通过 HTTPS 直接发送到你设置的接口。</small></label><div id="apiError" class="feedback-error" role="alert"></div></div><div class="dialog-actions"><button type="button" class="ghost-btn" id="clearApi">清除密钥</button><button type="submit" class="primary-btn">${icon('check')}保存本次会话</button></div></form>`;icons();if(!$('#infoDialog').open)$('#infoDialog').showModal();$('[data-close-settings]').onclick=()=>$('#infoDialog').close();$('#clearApi').onclick=()=>{state.api.key='';state.ppt.useAI=false;$('#apiKey').value='';toast('密钥已清除');};$('#apiForm').onsubmit=e=>{e.preventDefault();const endpoint=$('#apiEndpoint').value.trim().replace(/\/+$/,'');let url;try{url=new URL(endpoint)}catch{$('#apiError').textContent='请输入有效的接口地址';return;}if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash){$('#apiError').textContent='请输入不含凭证、查询参数的 HTTPS 接口地址';return;}state.api={endpoint,model:$('#apiModel').value.trim(),key:$('#apiKey').value.trim()};state.ppt.useAI=!!state.api.key;$('#infoDialog').close();if(state.route==='ppt')renderPpt();toast(state.api.key?'AI 接口已配置，可在 PPT 创作中使用':'已保存，本地模板模式可用');};}
$('#settingsBtn').onclick=openSettings;
function openConversion(id,files=[]){const tool=TOOLS.find(t=>t.id===id);if(!tool)return;modal={tool,files:[],results:[],busy:false,cancelled:false,target:tool.outputs[0],quality:.9};renderConversion();$('#convertDialog').showModal();if(files.length)addFiles(files);}
function renderConversion(){const m=modal,t=m.tool;$('#convertContent').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">FORMA CONVERT</div><h2>${t.name}</h2><p>${t.desc}</p></div><button class="close-btn" id="closeConvert" aria-label="关闭转换窗口">${icon('x')}</button></div><div class="dialog-body"><div class="dropzone modal-drop" id="modalDrop" role="button" tabindex="0" aria-label="选择要转换的文件">${icon('cloud-upload')}<p>拖入文件，或 <strong>点击选择</strong></p><small>${t.ext.map(e=>e.toUpperCase()).join(' / ')} · 单个最高 ${t.limit} MB · 最多 20 个</small></div><input id="convertUpload" type="file" accept="${t.ext.map(e=>'.'+e).join(',')}" multiple hidden><div id="fileList" class="file-list"></div><div class="settings-row"><label class="field"><span>输出格式</span><select id="targetFormat">${t.outputs.map(f=>`<option value="${f}">${f.toUpperCase()}</option>`).join('')}</select></label>${['image-convert','pdf-image','video-convert'].includes(t.id)?`<label class="field"><span>输出质量 <b id="qualityLabel">90%</b></span><input type="range" id="outputQuality" min="50" max="100" value="90" aria-label="输出质量"><small>${t.id==='video-convert'?'质量越高，输出体积通常越大':'PNG 为无损格式，不受此选项影响'}</small></label>`:''}</div><div class="note${t.id==='pdf-word'||t.id==='word-pdf'?' warn':''}">${icon('info')}${t.note}</div><div id="convertProgress" class="progress-area" hidden><div class="progress-label"><span id="progressText">正在准备…</span><span id="progressPercent">0%</span></div><div class="progress-track"><div id="progressBar"></div></div></div><div id="convertError" class="feedback-error" role="alert"></div><div id="convertResults"></div></div><div class="dialog-actions"><button class="ghost-btn" id="clearFiles">清空文件</button><button class="cancel-button" id="cancelConvert" hidden>取消任务</button><button class="primary-btn" id="startConvert">${icon('arrow-left-right')}开始转换</button><button class="primary-btn" id="downloadAll" hidden>${icon('download')}下载全部结果</button></div>`;icons();$('#closeConvert').onclick=closeConversion;$('#modalDrop').onclick=()=>{if(!modal.busy)$('#convertUpload').click();};$('#modalDrop').onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();$('#modalDrop').click();}};wireDrop($('#modalDrop'),files=>{if(!modal.busy)addFiles(files);});$('#convertUpload').onchange=e=>{addFiles([...e.target.files]);e.target.value='';};$('#targetFormat').onchange=e=>{m.target=e.target.value;invalidateResults();};$('#outputQuality')?.addEventListener('input',e=>{m.quality=e.target.value/100;$('#qualityLabel').textContent=e.target.value+'%';invalidateResults();});$('#clearFiles').onclick=()=>{m.files=[];invalidateResults();updateFileList();};$('#startConvert').onclick=runConversion;$('#cancelConvert').onclick=()=>{m.cancelled=true;stopVideoEngine();$('#progressText').textContent='正在取消，请稍候…';};$('#downloadAll').onclick=async()=>{try{const result=m.results.length===1?m.results[0]:await zipOutputs(m.results);download(newURL(result.blob),result.name);}catch(e){toast(e.message,true);}};updateFileList();}
function closeConversion(){if(modal?.busy){toast('任务仍在处理，请先点击「取消任务」');return;}$('#convertDialog').close();modal=null;if(state.route==='home'||state.route==='history')render();}
$('#convertDialog').addEventListener('cancel',e=>{if(modal?.busy){e.preventDefault();toast('请先取消正在处理的任务');}else{modal=null;if(state.route==='home'||state.route==='history')render();}});
function addFiles(files){if(!modal||modal.busy)return;let errors=[];for(const file of files){const error=validateFile(file,modal.tool);if(error){errors.push(`${file.name}：${error}`);continue;}if(modal.files.length>=20){errors.push('每次最多处理 20 个文件');break;}if(modal.files.reduce((s,f)=>s+f.size,0)+file.size>120*1024*1024){errors.push('本次文件总量不能超过 120 MB，请分批处理');break;}if(modal.files.some(f=>f.name===file.name&&f.size===file.size&&f.lastModified===file.lastModified))continue;modal.files.push(file);}invalidateResults();updateFileList();$('#convertError').textContent=errors.join('\n');}
function invalidateResults(){if(!modal)return;modal.results=[];$('#convertResults').innerHTML='';$('#downloadAll').hidden=true;$('#startConvert').hidden=false;$('#convertProgress').hidden=true;}
function updateFileList(){$('#fileList').innerHTML=modal.files.map((f,i)=>`<div class="selected-file">${icon('file')}<div class="file-details"><span>${esc(f.name)}</span><small>${bytes(f.size)} · ${ext(f.name).toUpperCase()}</small></div><span class="file-result" id="fileStatus${i}"></span><button class="remove-file" data-remove="${i}" aria-label="移除 ${esc(f.name)}">${icon('x')}</button></div>`).join('');$$('[data-remove]').forEach(b=>b.onclick=()=>{if(modal.busy)return;modal.files.splice(Number(b.dataset.remove),1);invalidateResults();updateFileList();});$('#startConvert').disabled=!modal.files.length;icons();}
function updateProgress(value,message){if(!modal)return;const n=Math.max(0,Math.min(100,Math.round(value*100)));$('#progressBar').style.width=n+'%';$('#progressPercent').textContent=n+'%';if(message)$('#progressText').textContent=message;}
async function runConversion(){const m=modal;if(!m||m.busy||!m.files.length)return;m.busy=true;m.cancelled=false;m.results=[];$('#convertError').textContent='';$('#convertProgress').hidden=false;$('#startConvert').hidden=true;$('#cancelConvert').hidden=false;$('#clearFiles').disabled=true;$('#targetFormat').disabled=true;if($('#outputQuality'))$('#outputQuality').disabled=true;$$('[data-remove]').forEach(b=>b.disabled=true);let failed=0;
  try{
    if(m.tool.id==='image-pdf'){
      const result=await imagesToPdf(m.files,p=>{if(m.cancelled)throw new Error('任务已取消');updateProgress(p,'正在将图片合并为 PDF…');});if(m.cancelled)throw new Error('任务已取消');m.results.push(result);trackTask(m.files.length>1?`${m.files[0].name} 等 ${m.files.length} 张图片`:m.files[0].name,m.tool.name,'success',result);m.files.forEach((f,i)=>$('#fileStatus'+i).textContent='已完成');
    }else{
      for(let i=0;i<m.files.length;i++){if(m.cancelled)break;const file=m.files[i];$('#fileStatus'+i).textContent='处理中';try{const result=await convertFile(file,m.tool,m.target,m.quality,(p,msg)=>{if(m.cancelled&&!['video','audio'].includes(m.tool.category))throw new Error('任务已取消');updateProgress((i+p)/m.files.length,msg||`正在转换 ${i+1} / ${m.files.length}：${file.name}`);});if(m.cancelled)break;m.results.push(result);trackTask(file.name,m.tool.name,'success',result);$('#fileStatus'+i).textContent='已完成';}catch(error){if(m.cancelled)break;failed++;$('#fileStatus'+i).textContent='失败';$('#fileStatus'+i).classList.add('failed');trackTask(file.name,m.tool.name,'error',null,error.message||String(error));$('#convertError').textContent+=`${file.name}：${error.message||String(error)}\n`;}}
    }
    if(m.cancelled){updateProgress(0,'任务已取消');toast('任务已取消，已完成的结果仍可下载');}else{updateProgress(1,`已完成 ${m.results.length} 个结果${failed?`，${failed} 个文件失败`:''}`);if(m.results.length)toast('转换完成，可以下载文件了');}
    if(m.results.length){$('#downloadAll').hidden=false;$('#downloadAll').innerHTML=icon('download')+(m.results.length===1?'下载转换结果':'打包下载全部结果');$('#convertResults').innerHTML=m.results.map((r,i)=>`<div class="result-panel">${icon('circle-check')}<span>${esc(r.name)}<small style="display:block;font-size:9px;margin-top:4px;opacity:.6">${bytes(r.blob.size)}</small></span><button class="download-btn" data-result="${i}">${icon('download')}下载</button></div>`).join('');$$('[data-result]').forEach(b=>b.onclick=()=>{const r=m.results[+b.dataset.result];download(newURL(r.blob),r.name);});}
  }catch(error){$('#convertError').textContent=error.message||String(error);toast(error.message||'转换失败',true);}
  finally{m.busy=false;$('#cancelConvert').hidden=true;$('#startConvert').hidden=false;$('#startConvert').innerHTML=icon('rotate-cw')+'重新转换';$('#startConvert').disabled=false;$('#clearFiles').disabled=false;$('#targetFormat').disabled=false;if($('#outputQuality'))$('#outputQuality').disabled=false;$$('[data-remove]').forEach(b=>b.disabled=false);icons();}
}
function renderPpt(){const p=state.ppt;$('#main').innerHTML=`<div class="fade-in"><div class="page-intro ppt-intro"><div><div class="eyebrow">FROM AN IDEA TO A GREAT PRESENTATION</div><h1>把想法，<em>变成好演示。</em></h1><p>从一个主题或一份文档出发，生成大纲，调整细节，导出属于你的 PPT。</p></div><button class="ghost-btn" id="pptSettings">${icon('settings-2')}AI 设置</button></div><div class="ppt-layout"><section class="creator-card"><div class="tabs" aria-label="内容来源">${[['prompt','sparkles','输入提示词'],['file','file-up','上传文件']].map(([id,ic,label])=>`<button data-ppt-mode="${id}" class="${p.mode===id?'active':''}" aria-pressed="${p.mode===id}">${icon(ic)} ${label}</button>`).join('')}</div><div class="creator-label">${p.mode==='prompt'?'你想表达什么？':'让文档成为一份演示'}<small>${p.mode==='prompt'?'最多 12,000 字':'支持内容型文件'}</small></div>${p.mode==='prompt'?`<textarea id="pptPrompt" class="prompt-input" maxlength="12000" placeholder="例如：为产品团队制作一份关于「提升用户体验」的演示，介绍当前问题、改进思路与行动计划。\n\n也可以粘贴你的笔记、内容提纲或已有资料。">${esc(p.text)}</textarea><div class="prompt-examples"><button data-example="0">✧ 季度工作汇报</button><button data-example="1">✧ 产品发布方案</button><button data-example="2">✧ 读书分享会</button></div>`:`<div class="dropzone file-import-zone" id="pptDrop" role="button" tabindex="0" aria-label="选择生成 PPT 的源文件">${icon(p.fileName?'file-check-2':'cloud-upload')}<strong>${p.fileName?esc(p.fileName):'拖入文档，或点击选择文件'}</strong><small>TXT、Markdown、DOCX、PDF · 最高 15 MB</small></div><input id="pptSource" type="file" accept=".txt,.md,.docx,.pdf" hidden><div class="source-info" id="sourceInfo">${p.source?`已读取 ${p.source.length.toLocaleString()} 字 · 将提取核心内容生成大纲`:'只提取文字，扫描版 PDF 暂不支持。文件保留在你的设备上。'}</div>`}<div class="creator-divider"></div><div class="creator-label">选择演示风格<small>16:9 宽屏 · 可编辑元素</small></div><div class="theme-options">${Object.entries(THEMES).map(([id,t])=>`<button class="theme-option${p.theme===id?' active':''}" data-theme="${id}" aria-pressed="${p.theme===id}"><span class="theme-swatch ${id}"></span>${t.name}</button>`).join('')}</div><div class="settings-row"><label class="field"><span>演示页数</span><select id="pptPages">${[4,6,8,10,12].map(n=>`<option value="${n}"${p.pages===n?' selected':''}>${n} 页${n===8?' · 推荐':''}</option>`).join('')}</select></label><label class="field"><span>创作模式</span><select id="pptAiMode"><option value="local"${!p.useAI?' selected':''}>本地模板排版</option><option value="ai"${p.useAI?' selected':''}>AI 内容扩写${state.api.key?'':'（需设置接口）'}</option></select></label></div><div class="ai-mode"><span>${icon(p.useAI?'sparkles':'shield-check')}${p.useAI?'文字将发送至你配置的模型接口':'本地生成结构模板，请补充实际信息'}</span><button id="configureAI">${p.useAI?'修改接口':'启用 AI 扩写'}</button></div><button class="primary-btn generate-button" id="generatePpt"${p.generating?' disabled':''}>${p.generating?'<span class="spinner"></span>正在整理内容…':icon('sparkles')+(p.outline.length?'重新生成大纲':'生成演示大纲')}</button><div id="pptError" class="feedback-error" role="alert"></div></section><section class="preview-panel"><div class="preview-heading">你的演示，即将成形<small>风格预览</small></div><div class="slide-preview ${p.theme}" id="slidePreview"><div class="preview-kicker">IDEAS INTO MOTION</div><h2 id="previewTitle">${esc(p.outline[0]?.title||'让每一个想法，\n都有清晰的表达。').replace(/\n/g,'<br>')}</h2><p id="previewSubtitle">${esc(p.outline[0]?.bullets[0]||'从灵感到呈现，把专注留给内容。')}</p><div class="preview-foot"><span>FORMA PRESENTATION</span><span>01 / ${String(p.pages).padStart(2,'0')}</span></div></div><div class="preview-detail"><span>16:9 · ${p.pages} 页</span><span>${THEMES[p.theme].name}</span></div><div class="preview-features"><div>${icon('type')}文字、图形均可在 PowerPoint 中编辑</div><div>${icon('list-tree')}先看大纲，再调整，表达由你掌控</div><div>${icon('download')}导出标准 .pptx 文件，无需注册</div><div>${icon('lock-keyhole')}本地模板模式，内容无需上传</div></div><div class="note" style="margin-top:24px">${icon('lightbulb')}本地模式提供结构与排版；需要基于主题自动撰写具体内容时，可接入自己的 AI 模型。</div></section></div><section id="outlineArea"></section></div>`;wirePpt();renderOutline();icons();}
const examples=['制作一份季度工作汇报，包含本季度重点工作、实际成果、遇到的问题、复盘与下季度行动计划。请为真实数据保留填写位置。','制作一份新产品发布方案，围绕用户痛点、产品价值、关键功能、发布节奏和后续迭代展开。','制作一份读书分享会演示，围绕书籍主题、核心观点、印象深刻的内容、个人思考与讨论问题展开。'];
function wirePpt(){const p=state.ppt;$$('[data-ppt-mode]').forEach(b=>b.onclick=()=>{if(p.generating)return;p.mode=b.dataset.pptMode;renderPpt();});$('#pptPrompt')?.addEventListener('input',e=>{p.text=e.target.value;});$$('[data-example]').forEach(b=>b.onclick=()=>{p.text=examples[+b.dataset.example];$('#pptPrompt').value=p.text;$('#pptPrompt').focus();});$$('[data-theme]').forEach(b=>b.onclick=()=>{if(p.generating)return;p.theme=b.dataset.theme;renderPpt();});$('#pptPages').onchange=e=>{p.pages=+e.target.value;renderPpt();};$('#pptAiMode').onchange=e=>{if(e.target.value==='ai'&&!state.api.key){e.target.value='local';openSettings();}else{p.useAI=e.target.value==='ai';renderPpt();}};$('#pptSettings').onclick=openSettings;$('#configureAI').onclick=openSettings;$('#generatePpt').onclick=generateOutline;
  const drop=$('#pptDrop');if(drop){drop.onclick=()=>{if(!p.generating)$('#pptSource').click();};drop.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();drop.click();}};wireDrop(drop,files=>importPptFile(files[0]));$('#pptSource').onchange=e=>importPptFile(e.target.files[0]);}
  const generateButton=$('#generatePpt');if(!p.generating)generateButton.innerHTML=icon('sparkles')+'一键生成 PPT';
  generateButton.onclick=async()=>{const generated=await generateOutline();if(generated)await exportPpt();};
  const previewButton=document.createElement('button');previewButton.className='ghost-btn';previewButton.style.cssText='width:100%;margin-top:10px';previewButton.textContent='先生成大纲，自由编辑';previewButton.disabled=p.generating;previewButton.onclick=generateOutline;generateButton.after(previewButton);
}
async function importPptFile(file){const p=state.ppt;if(!file||p.generating)return;const error=validateFile(file,{ext:['txt','md','pdf','docx'],limit:15});if(error){toast(error,true);return;}p.generating=true;$('#sourceInfo').textContent='正在提取文档文字…';$('#generatePpt').disabled=true;try{const text=await readText(file);if(!text.trim())throw new Error('文档中没有可读取的文字');if(text.length>100000)throw new Error('文档超过 10 万字，请精简后再导入');p.source=text;p.fileName=file.name;p.outline=[];toast('已读取文件，可以生成演示大纲');}catch(e){toast(e.message,true);}finally{p.generating=false;renderPpt();}}
async function aiOutline(text,count){const a=state.api;if(!a.key)throw new Error('请先在 AI 设置中填写接口与密钥');const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),60000);
  try{const response=await fetch(a.endpoint.replace(/\/chat\/completions$/,'')+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+a.key},signal:controller.signal,body:JSON.stringify({model:a.model,messages:[{role:'system',content:`你是中文演示文稿编辑。根据用户主题或资料生成 ${count} 页演示大纲。只返回 JSON 数组，不加代码围栏。每个元素为 {"title":"页标题","bullets":["要点一","要点二","要点三"]}。第一页为封面，最后一页为总结。每页最多4条要点，每条不超过100字。不要编造统计数据、案例、引用或用户未提供的事实。不确定的数据请明确标注待补充。内容具体、逻辑清晰、适合直接展示。`},{role:'user',content:text.slice(0,18000)}],max_tokens:4000})});if(!response.ok)throw new Error(`模型服务返回 ${response.status}，请检查接口、密钥、模型与余额`);const data=await response.json();const content=data.choices?.[0]?.message?.content;if(typeof content!=='string')throw new Error('模型未返回文本内容，请更换兼容的模型');let parsed;try{parsed=JSON.parse(content.replace(/^\s*```(?:json)?\s*/,'').replace(/\s*```\s*$/,''));}catch{throw new Error('模型返回内容不是有效大纲 JSON，请重试');}return validateOutline(parsed,count);}catch(e){if(e.name==='AbortError')throw new Error('AI 请求超过 60 秒，请重试或使用本地模板');if(e instanceof TypeError)throw new Error('无法连接模型接口，请确认网络和服务的浏览器跨域（CORS）支持');throw e;}finally{clearTimeout(timeout);}}
async function generateOutline(){const p=state.ppt;if(p.generating)return;const text=(p.mode==='prompt'?p.text:p.source).trim();if(text.length<5){$('#pptError').textContent=p.mode==='file'?'请先导入有文字内容的文件':'请用至少 5 个字描述演示主题';return;}p.generating=true;$('#pptError').textContent='';$('#generatePpt').disabled=true;$('#generatePpt').innerHTML='<span class="spinner"></span>'+(p.useAI?'AI 正在创作大纲…':'正在整理演示结构…');
  try{if(p.useAI)p.outline=await aiOutline(text,p.pages);else{await new Promise(r=>setTimeout(r,400));p.outline=localOutline(text,p.pages,p.mode);}toast(p.useAI?'AI 大纲已生成，可编辑后导出':'模板大纲已生成，请检查并补充实际内容');}catch(e){$('#pptError').textContent=e.message;p.generating=false;$('#generatePpt').disabled=false;$('#generatePpt').innerHTML=icon('sparkles')+'重试生成';icons();return;}finally{p.generating=false;}
  renderPpt();$('#outlineArea').scrollIntoView({behavior:'smooth',block:'start'});return true;
}
function renderOutline(){const p=state.ppt;if(!p.outline.length){$('#outlineArea').innerHTML='';return;}$('#outlineArea').innerHTML=`<div class="outline-panel"><div class="outline-header"><div><h2>把内容，调整成你的表达。</h2><p>${p.outline.length} 页大纲 · 点击文字即可编辑 · ${p.useAI?'AI 内容请核对事实与来源':'本地模板包含待补充的通用框架'}</p></div><div class="outline-actions"><button class="ghost-btn" id="downloadOutline">${icon('file-text')}下载大纲</button><button class="primary-btn" id="exportPpt">${icon('download')}导出 PPTX</button></div></div><div class="outline-grid">${p.outline.map((s,i)=>`<div class="outline-item"><div class="outline-number"><span>SLIDE ${String(i+1).padStart(2,'0')}</span><span>${i===0?'封面':i===p.outline.length-1?'结束页':'内容页'}</span></div><input data-slide-title="${i}" value="${esc(s.title)}" maxlength="60" aria-label="第 ${i+1} 页标题"><textarea data-slide-body="${i}" aria-label="第 ${i+1} 页要点，每行一条" maxlength="1000">${esc(s.bullets.join('\n'))}</textarea></div>`).join('')}</div><div class="note">${icon('info')}每页最多展示 4 条要点；文字较多时会自动缩小。建议用简短句子，并在 PowerPoint 中核对最终排版。</div></div>`;
  $$('[data-slide-title]').forEach(input=>input.oninput=()=>{p.outline[+input.dataset.slideTitle].title=input.value;if(+input.dataset.slideTitle===0&&$('#previewTitle'))$('#previewTitle').textContent=input.value;});$$('[data-slide-body]').forEach(input=>input.oninput=()=>{p.outline[+input.dataset.slideBody].bullets=input.value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,4).map(x=>x.slice(0,240));});$('#downloadOutline').onclick=()=>{const text=p.outline.map((s,i)=>`# ${i+1}. ${s.title}\n\n${s.bullets.map(b=>'- '+b).join('\n')}`).join('\n\n');download(newURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),base(p.outline[0].title)+'.md');};$('#exportPpt').onclick=exportPpt;icons();}
async function exportPpt(){const p=state.ppt,btn=$('#exportPpt');btn.disabled=true;btn.innerHTML='<span class="spinner"></span>正在导出…';try{if(p.outline.some(s=>!s.title.trim()))throw new Error('请为每一页填写标题后再导出');await loadScript('pptxgen.js');const presentation=buildPresentation(window.PptxGenJS,p.outline,p.theme);const blob=await presentation.write({outputType:'blob'});const result={blob,name:base(p.outline[0].title)+'.pptx'};const task=trackTask(result.name,'PPT 生成','success',result);download(task.url,task.output);toast('PPT 已导出，文字与图形均可继续编辑');}catch(e){toast(e.message||'导出失败，请重试',true);}finally{btn.disabled=false;btn.innerHTML=icon('download')+'导出 PPTX';icons();}}
window.addEventListener('beforeunload',()=>{for(const url of runtimeURLs)URL.revokeObjectURL(url);});
routeTo(location.hash.slice(1)||'home');
